def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'

    # Extract opponent actions efficiently
    op = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in my if x == 'D')

    # Recent windows
    w = 10
    recent = op[-w:]
    r_c = sum(1 for x in recent if x == 'C')
    r_d = len(recent) - r_c

    last_op = op[-1]
    last_my = my[-1]
    remaining = 100 - n

    # Endgame: exploit cooperative opponents in final rounds
    if remaining <= 3:
        if opp_c * 2 >= n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Detect always-defect / mostly-defect opponent
    if opp_d >= n - 2 and n >= 6:
        # Rarely test cooperation to check for strategy change
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Opponent almost purely cooperative: exploit but carefully
    if opp_d == 0 and n >= 20:
        # Defect occasionally for big gains, but avoid provoking
        if n % 9 == 0:
            return 'D'
        return 'C'

    # Opponent highly cooperative overall
    if opp_c * 4 >= n * 3:
        # Mostly cooperate; rare probe
        if last_op == 'D':
            # They defected - retaliate once, then forgive
            if r_d >= 2 and rng.random() < 0.5:
                return 'D'
            return 'C'
        # Occasionally test exploitation when cushion is high
        if n >= 30 and my_d * 4 < n and n % 11 == 0:
            return 'D'
        return 'C'

    # Opponent mostly defecting: defect, occasional forgiveness probe
    if opp_d * 3 >= n * 2:
        if n % 7 == 0:
            return 'C'
        return 'D'

    # Moderate opponent: tit-for-tat with forgiveness and anti-spiral
    if last_op == 'D':
        # If we defected last too, try to break DD spiral
        if last_my == 'D':
            if r_d <= 2 and rng.random() < 0.5:
                return 'C'
            return 'D'
        # Punish once
        if r_d >= 3:
            return 'D'
        # Mild forgiveness for isolated defection
        if opp_c * 2 >= n and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last
    if last_my == 'D':
        # Return to cooperation
        return 'C'
    # Occasional probe only if we've been very cooperative and they seem forgiving
    if n >= 25 and opp_d * 5 <= n and my_d * 5 <= n:
        if n % 17 == 0 and rng.random() < 0.4:
            return 'D'
    return 'C'
